/// One row of Raven's `spawns` of `g_spawn.c`, the `spawn_t` record with the spawn function as a Swift function value.
/// C storage cannot hold the address of a Swift function, so the table is hand data on `GameWorld`.
struct SpawnRow {
    let name: String
    let spawn: (Entity) -> Void
}

/// One row of Raven's `gameCvarTable` of `g_main.c`, the `cvarTable_t` record with the cvar handle as a key path into `GameStorage`.
/// A nil key path is Raven's NULL handle, a cvar the module registers and never reads.
struct CvarTableRow {
    let vmCvar: KeyPath<GameStorage, JKAMP.VmCvar>?
    let cvarName: String
    let defaultString: String
    let cvarFlags: Int32
    var modificationCount: Int32
    let trackChange: Bool
    let teamShader: Bool
}

/// Raven's `__DATE__`, which is `unknown` because Swift has no compile-time date.
let buildDate = "unknown"

/// Raven's `SABERINVALID` of w_saber.c, true when a saber, its owner, or the other entity cannot take a knockdown test.
/// A saber lock that ended less than 100 ms ago also makes the test true.
func saberInvalid(_ saberent: Entity, _ saberOwner: Entity, _ other: Entity) -> Bool {
    // Raven tests the three entities for NULL first.
    // Swift holds each one as a non-optional value, so these tests have no form.
    return !saberent.inuse
        || !saberOwner.inuse
        || !other.inuse
        || saberOwner.client == nil
        || other.client == nil
        || saberOwner.client!.ps.saberEntityNum == 0
        || saberOwner.client!.ps.saberLockTime > (level.time - 100)
}

/// The one instance. `vmMain` has no context argument and the engine calls the module from one thread, so this is not isolated.
nonisolated(unsafe) var world = GameWorld()

/// The string pool of rule 9, the only source of a runtime `char *`.
var strings: StringPool { world.strings }
